-- CATEGORY EAA TABLE: Expected Annual Articles per category (Scott rulings 2026-07-12; STANDALONE, not tethered to reviews).
-- EAA = clamp(annual_transactions / 12, 18, 40). Articles Score = 85 * min(1, AVE/EAA);
--   AVE = sum over articles of max(0, 1 - age_months/18)  [18-month linear decay to zero].
-- non_authored=true: infrastructure/civic objects that do not publish articles - floored + flagged.
-- Provenance: /12 cadence anchor + 18/40 clamp + 18-mo decay = PRIOR (launch, pending validation program).
CREATE TABLE IF NOT EXISTS exp_category_eaa (
  gcid text PRIMARY KEY REFERENCES gbp_categories(gcid),
  annual_transactions numeric NOT NULL,
  eaa numeric NOT NULL,
  band text NOT NULL CHECK (band IN ('floor','mid','cap')),
  eaa_professional numeric,
  band_professional text,
  confidence text,
  non_authored boolean NOT NULL DEFAULT false,
  method_version text NOT NULL DEFAULT 'articles_v1_standalone',
  provenance text NOT NULL DEFAULT 'prior'
);
ALTER TABLE exp_category_eaa ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read eaa" ON exp_category_eaa FOR SELECT TO anon, authenticated USING (true);
